package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for BigMatrixImpl.operate(BigDecimal[] v)
 */
public class BigMatrixImpl_operate_TriageGen0Test {

    @Test
    public void testOperate_Success() {
        // Setup a 2x3 matrix
        // [ 1, 2, 3 ]
        // [ 4, 5, 6 ]
        BigDecimal[][] data = {
            {new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("3")},
            {new BigDecimal("4"), new BigDecimal("5"), new BigDecimal("6")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector to multiply: [ 1, 0, 2 ]
        // Expected result:
        // Row 0: 1*1 + 2*0 + 3*2 = 7
        // Row 1: 4*1 + 5*0 + 6*2 = 16
        BigDecimal[] v = {new BigDecimal("1"), new BigDecimal("0"), new BigDecimal("2")};
        BigDecimal[] expected = {new BigDecimal("7"), new BigDecimal("16")};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_WrongLength_ThrowsException() {
        // Setup a 2x2 matrix
        BigDecimal[][] data = {
            {BigDecimal.ONE, BigDecimal.ONE},
            {BigDecimal.ONE, BigDecimal.ONE}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector length is 3, but column dimension is 2
        BigDecimal[] v = {BigDecimal.ONE, BigDecimal.ONE, BigDecimal.ONE};

        try {
            matrix.operate(v);
            Assert.fail("Expected IllegalArgumentException due to wrong vector length");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("vector has wrong length", e.getMessage());
        }
    }

    @Test
    public void testOperate_SingleElementMatrix() {
        // Setup a 1x1 matrix
        BigDecimal[][] data = {{new BigDecimal("5.5")}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("2")};
        BigDecimal[] expected = {new BigDecimal("11.0")};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_ZeroMatrix() {
        // Setup a 2x2 zero matrix
        BigDecimal[][] data = {
            {BigDecimal.ZERO, BigDecimal.ZERO},
            {BigDecimal.ZERO, BigDecimal.ZERO}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("10"), new BigDecimal("20")};
        BigDecimal[] expected = {BigDecimal.ZERO, BigDecimal.ZERO};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_NegativeValues() {
        // Setup a 2x2 matrix
        BigDecimal[][] data = {
            {new BigDecimal("-1"), new BigDecimal("2")},
            {new BigDecimal("3"), new BigDecimal("-4")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector: [ 2, -1 ]
        // Row 0: (-1 * 2) + (2 * -1) = -4
        // Row 1: (3 * 2) + (-4 * -1) = 6 + 4 = 10
        BigDecimal[] v = {new BigDecimal("2"), new BigDecimal("-1")};
        BigDecimal[] expected = {new BigDecimal("-4"), new BigDecimal("10")};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }
}
